package com.keyforge.nativeload;
import com.keyforge.iiq.config.SchemaName;import com.keyforge.iiq.parquet.ParquetIds;import java.sql.*;import java.time.ZoneOffset;import java.util.*;
/** Native Workflow storage; approval declarations remain structured source JSON. */
public final class NativeWorkflowRepository {private final String schema,table;public enum Outcome{INSERTED,UPDATED}public NativeWorkflowRepository(String s){schema=SchemaName.validate(s);table=schema+".kf_workflow_definition";}public String targetTable(){return table;}public void ensure(Connection c)throws SQLException{try(Statement s=c.createStatement()){s.execute("CREATE SCHEMA IF NOT EXISTS "+schema);s.execute("CREATE TABLE IF NOT EXISTS "+table+" (workflowid uuid PRIMARY KEY,source_id text,name text,type text,handler text,description text,task_type text,definition jsonb,record_hash text,source_system text,source_interface text,source_object_type text,src_object_id text,src_natural_key text,extraction_run_id text,created_at timestamptz,modified_at timestamptz,extracted_at timestamptz NOT NULL DEFAULT now(),is_deleted boolean NOT NULL DEFAULT false,deleted_at timestamptz)");for(String col:List.of("source_id text","task_type text","definition jsonb","record_hash text","source_system text","source_interface text","source_object_type text","src_object_id text","src_natural_key text","extraction_run_id text","is_deleted boolean NOT NULL DEFAULT false","deleted_at timestamptz"))s.execute("ALTER TABLE "+table+" ADD COLUMN IF NOT EXISTS "+col);}}public static String id(String source){String x=ParquetIds.canonicalUuid(source);return x==null?ParquetIds.deterministicUuid("native-workflow|"+source):x;}public Outcome upsert(Connection c,NativeWorkflowRecord r)throws SQLException{String sql="INSERT INTO "+table+"(workflowid,source_id,name,type,handler,description,task_type,definition,record_hash,source_system,source_interface,source_object_type,src_object_id,src_natural_key,extraction_run_id,created_at,modified_at,is_deleted,deleted_at) VALUES(?::uuid,?,?,?,?,?, ?,?::jsonb,?,?,?,?,?,?,?,?,?,false,null) ON CONFLICT(workflowid) DO UPDATE SET source_id=excluded.source_id,name=excluded.name,type=excluded.type,handler=excluded.handler,description=excluded.description,task_type=excluded.task_type,definition=excluded.definition,record_hash=excluded.record_hash,source_system=excluded.source_system,source_interface=excluded.source_interface,source_object_type=excluded.source_object_type,src_object_id=excluded.src_object_id,src_natural_key=excluded.src_natural_key,extraction_run_id=excluded.extraction_run_id,created_at=excluded.created_at,modified_at=excluded.modified_at,extracted_at=now(),is_deleted=false,deleted_at=null RETURNING (xmax=0) inserted";try(PreparedStatement p=c.prepareStatement(sql)){int i=1;p.setString(i++,id(r.sourceId));p.setString(i++,r.sourceId);p.setString(i++,r.name);p.setString(i++,r.type);p.setString(i++,r.handler);p.setString(i++,r.description);p.setString(i++,r.taskType);p.setString(i++,r.definition);p.setString(i++,r.hash);p.setString(i++,r.sourceSystem);p.setString(i++,"native_iiq_java_api");p.setString(i++,"sailpoint.object.Workflow");p.setString(i++,r.sourceId);p.setString(i++,r.name);p.setString(i++,r.runId);p.setObject(i++,r.created==null?null:r.created.atOffset(ZoneOffset.UTC));p.setObject(i,r.modified==null?null:r.modified.atOffset(ZoneOffset.UTC));try(ResultSet x=p.executeQuery()){return x.next()&&x.getBoolean(1)?Outcome.INSERTED:Outcome.UPDATED;}}}public int sweep(Connection c,Collection<String>ids)throws SQLException{if(ids.isEmpty())return 0;String sql="UPDATE "+table+" SET is_deleted=true,deleted_at=now() WHERE is_deleted=false AND workflowid NOT IN ("+String.join(",",Collections.nCopies(ids.size(),"?::uuid"))+")";try(PreparedStatement p=c.prepareStatement(sql)){int i=1;for(String id:ids)p.setString(i++,id);return p.executeUpdate();}}}
